#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# Generated by opencode (skill: sudo-handoff)
#
# Purpose : <one line: what this script achieves>
# Impact  : <read-only | mutating: which files/services/interfaces change>
# Rollback: <exact command, or "not applicable">
# Usage   : sudo <this file> [--check]
# Log     : /tmp/<same basename>.log, owned by the invoking user afterwards
#
# Design notes:
#   - `set -e` is intentionally NOT used: every command goes through run(),
#     which records the exit code and continues, so one failing check does
#     not hide the remaining output.
#   - `pipefail` is intentionally NOT used: pipelines ending in `head`/`grep -q`
#     would otherwise report SIGPIPE (141) as a hard failure.
#   - The whole run is piped through `tee` so the log is complete and flushed
#     before the script exits.
# ---------------------------------------------------------------------------
set -u
umask 077

if [ -z "${BASH_VERSION:-}" ]; then
  printf 'ERROR: this script requires bash.\n' >&2
  exit 2
fi

SCRIPT_PATH="$(readlink -f -- "${BASH_SOURCE[0]}")"
SCRIPT_NAME="$(basename -- "${SCRIPT_PATH}" .sh)"
LOG="${LOG:-/tmp/${SCRIPT_NAME}.log}"
OWNER="${SUDO_USER:-$(id -un)}"
CHECK_ONLY=0
OK=0
FAILED=0
SKIPPED=0

if [ "${1:-}" = "--check" ]; then
  CHECK_ONLY=1
elif [ $# -gt 0 ]; then
  printf 'ERROR: unknown argument: %s\nUsage: sudo %s [--check]\n' "$1" "$SCRIPT_PATH" >&2
  exit 2
fi

if [ "${EUID}" -ne 0 ]; then
  printf 'ERROR: root privileges required. Run:\n' >&2
  printf '  sudo %s%s\n' "$SCRIPT_PATH" "$([ "$CHECK_ONLY" -eq 1 ] && printf ' --check')" >&2
  exit 2
fi

# Create the log as root, then hand it to the invoking user immediately so the
# agent can read it after the run without further privilege escalation.
: > "$LOG"
chown -- "${OWNER}:" "$LOG" 2>/dev/null || true
chmod 0600 "$LOG" 2>/dev/null || true

section() {
  printf '\n----- %s -----\n' "$1"
}

run() {
  # run <crit|soft> "<description>" -- <command> [args...]
  local mode="$1" desc="$2"
  shift 2
  [ "${1:-}" = "--" ] && shift

  printf '\n$ '
  printf '%q ' "$@"
  printf '\n'

  "$@"
  local rc=$?
  if [ "$rc" -eq 0 ]; then
    OK=$((OK + 1))
    printf '[ok] %s\n' "$desc"
    return 0
  fi

  FAILED=$((FAILED + 1))
  printf '[FAIL rc=%d] %s\n' "$rc" "$desc"
  if [ "$mode" = "crit" ]; then
    printf 'ABORT: critical step failed, see output above.\n'
    exit 1
  fi
  return 0
}

require_cmd() {
  local c
  for c in "$@"; do
    if ! command -v -- "$c" >/dev/null 2>&1; then
      FAILED=$((FAILED + 1))
      printf '[FAIL] required command missing: %s\n' "$c"
      return 1
    fi
  done
  return 0
}

confirm_destructive() {
  # Gate for irreversible steps. Use it as an `if` condition, not through run():
  #   if confirm_destructive "delete /var/lib/foo"; then
  #     run crit "delete ..." -- rm -- /var/lib/foo
  #   fi
  # Enable explicitly at invocation time:
  #   sudo CONFIRM=yes /tmp/opencode-....sh
  if [ "${CONFIRM:-}" = "yes" ]; then
    printf '[confirmed] destructive step enabled via CONFIRM=yes\n'
    return 0
  fi
  SKIPPED=$((SKIPPED + 1))
  printf '[SKIP] destructive step not confirmed.\n'
  printf '       reason: %s\n' "$*"
  printf '       re-run with: sudo CONFIRM=yes %s\n' "$SCRIPT_PATH"
  return 1
}

preflight() {
  section "PREFLIGHT (read-only)"
  # Read-only discovery only. Use:
  #   run soft "description" -- command --with --args
}

apply() {
  section "APPLY (mutating)"
  # Mutating steps. Use `crit` when later steps depend on success:
  #   run crit "description" -- command --with --args
  #
  # Back up config files before editing them:
  #   run crit "back up <file>" -- cp -a -- <file> <file>.bak-$(date +%Y%m%d%H%M%S)
}

verify() {
  section "VERIFY"
  # Prove the change, with the expected value as a comment:
  #   run soft "expect 192.168.77.1/24 on <if>" -- ip -4 addr show <if>
  #   run soft "expect ip_forward=1" -- sysctl net.ipv4.ip_forward
}

main() {
  printf '=== %s ===\n' "$SCRIPT_NAME"
  printf 'host=%s user=%s euid=%d check_only=%d\n' "$(hostname)" "$OWNER" "$EUID" "$CHECK_ONLY"
  printf 'started=%s\n' "$(date -Is)"

  preflight
  if [ "$CHECK_ONLY" -eq 0 ]; then
    apply
    verify
  fi

  printf '\n================ SUMMARY ================\n'
  printf 'ok=%d failed=%d skipped=%d\n' "$OK" "$FAILED" "$SKIPPED"
  printf 'log=%s\n' "$LOG"
  printf 'finished=%s\n' "$(date -Is)"

  [ "$FAILED" -eq 0 ]
}

main 2>&1 | tee -a -- "$LOG"
RC=${PIPESTATUS[0]}

# tee has exited here, so the log is complete before ownership is finalised.
chown -- "${OWNER}:" "$LOG" 2>/dev/null || true
chmod 0600 "$LOG" 2>/dev/null || true
printf 'Log: %s (exit %d)\n' "$LOG" "$RC" >&2
exit "$RC"
